#ifndef LANEC_DI_ROUTINES_H
#define LANEC_DI_ROUTINES_H
/* DISPLAY_INTERFACE_ROUTINES (Luminary099 and Comanche055) as native
 * routines of the control-transfer ABI (docs/NATIVE_TRANSFER_ABI.md). Every
 * entry and every point where a callee returns into the file that a Lane C
 * suite verifies is registered at its physical address and runs that
 * module's lanec_di_*_dispatch; LANEC_OUT_OF_SCOPE is EXEC_OUT_OF_SCOPE.
 * Each module has its own tables, one per mission, in its own source file
 * (src/lanec_di_<module>_routines.c, generated by tools/lanec/routines.py
 * di), so a flight-store module links one module's code alone; a program
 * registers the tables of the modules it runs.
 * The modules use the superbank, the interrupt-enable state and output
 * channel 11 (MAKEPLAY's KEY REL light): the LM routines take a p66_bias_io
 * and channel 11 from program->hardware (refusing when it is NULL), the CM
 * routines a cm_native_io. */
#include "agc_transfer.h"
#include "lanec.h"
#include "p66_bias.h"
#include "cm_native_image.h"
extern const agc_routine_table lanec_di_lm_dsp, lanec_di_lm_mark, lanec_di_lm_play, lanec_di_lm_sleep,
    lanec_di_lm_idle, lanec_di_lm_nvdsp;
extern const agc_routine_table lanec_di_cm_dsp, lanec_di_cm_mark, lanec_di_cm_play, lanec_di_cm_sleep,
    lanec_di_cm_idle, lanec_di_cm_nvdsp;
/* every module's table, in module order (addresses), for a program that registers them all */
#define LANEC_DI_LM_TABLES &lanec_di_lm_dsp, &lanec_di_lm_mark, &lanec_di_lm_play, &lanec_di_lm_sleep, \
    &lanec_di_lm_idle, &lanec_di_lm_nvdsp
#define LANEC_DI_CM_TABLES &lanec_di_cm_dsp, &lanec_di_cm_mark, &lanec_di_cm_play, &lanec_di_cm_sleep, \
    &lanec_di_cm_idle, &lanec_di_cm_nvdsp
#define LANEC_DI_TABLE_COUNT 6u
/* Copies N tables (such as a family's LANEC_*_TABLES) into a program's table
 * list at TO; returns N. */
static inline uint8_t lanec_put_tables(agc_routine_table *to, const agc_routine_table *const *from, uint8_t n)
{
    uint8_t i;
    for (i = 0; i < n; ++i) to[i] = *from[i];
    return n;
}
/* A module's routine: the module's dispatch on the mission's device record
 * (src/lanec_di_routines.c). */
typedef enum lanec_status (*lanec_di_dispatch)(apollo_overlay_state *, lanec_io *, enum lanec_mission);
enum exec_status lanec_di_run_lm(const agc_native_program *, apollo_overlay_state *, p66_bias_io *, lanec_di_dispatch);
enum exec_status lanec_di_run_cm(const agc_native_program *, apollo_overlay_state *, cm_native_io *, lanec_di_dispatch);
#endif
